# -*- coding: utf-8 -*-
"""
Historical Data Factory for MT4 (Replaces OANDA)
Note: MT4 file bridge has limited historical data capability.
For full historical data, you may need to export from MT4 separately.
"""

from datetime import datetime, timedelta
import calendar
import logging

logger = logging.getLogger(__name__)

MAX_BATCH = 5000
DEFAULT_BATCH = 500


class MT4CandlesFactory:
    """
    MT4 Candles Factory - Generate candle requests for MT4.
    
    Note: MT4 file bridge does not provide direct historical candle data.
    This class provides a compatible interface but uses simulated or
    cached data. For production, you should export historical data
    from MT4 to a CSV file and load it separately.
    """
    
    def __init__(self, instrument, params=None):
        """
        Initialize MT4 candles factory.
        
        Parameters
        ----------
        instrument : string (required)
            the instrument (e.g., 'EURUSD' -> converted to 'EURUSD')
        params: params (optional)
            parameters specifying the historical range
        """
        self.instrument = instrument.replace('_', '')  # Convert EURUSD to EURUSD
        self.params = params or {}
        self._candles_cache = []
        self._load_cached_data()
    
    def _load_cached_data(self):
        """Load cached historical data if available"""
        # Try to load from CSV if exists
        import os
        cache_file = f"mt4_history_{self.instrument}.csv"
        if os.path.exists(cache_file):
            try:
                import csv
                with open(cache_file, 'r') as f:
                    reader = csv.DictReader(f)
                    self._candles_cache = list(reader)
                logger.info(f"Loaded {len(self._candles_cache)} candles from {cache_file}")
            except Exception as e:
                logger.warning(f"Could not load cache: {e}")
    
    def get_candles(self):
        """
        Get candles from MT4 (simulated or cached).
        
        Returns:
            List of candle dicts with keys: time, open, high, low, close, volume
        """
        if self._candles_cache:
            return self._candles_cache
        
        # Return simulated candles based on current price
        return self._generate_simulated_candles()
    
    def _generate_simulated_candles(self):
        """Generate simulated candles for testing"""
        from mt4_price_provider import get_mt4_prices
        import random
        
        mt4 = get_mt4_prices()
        price_data = mt4.get_price(self.instrument)
        
        if not price_data.get('success'):
            return []
        
        current_price = price_data.get('mid', 1.0950)
        candles = []
        
        # Parse params
        granularity = self.params.get('granularity', 'M15')
        count = self.params.get('count', DEFAULT_BATCH)
        _from = self.params.get('from')
        
        # Determine time interval in minutes
        granularity_map = {
            'S5': 5/60, 'S10': 10/60, 'S15': 15/60, 'S30': 30/60,
            'M1': 1, 'M5': 5, 'M15': 15, 'M30': 30,
            'H1': 60, 'H4': 240, 'D': 1440, 'W': 10080
        }
        interval_minutes = granularity_map.get(granularity, 15)
        
        # Generate candles
        now = datetime.now()
        for i in range(min(count, MAX_BATCH)):
            # Simulate price variation
            variation = random.uniform(-0.005, 0.005) * (i + 1) / count
            candle_time = now - timedelta(minutes=interval_minutes * (count - i))
            
            candle = {
                'time': candle_time.strftime('%Y-%m-%dT%H:%M:%SZ'),
                'open': round(current_price * (1 + variation - 0.001), 5),
                'high': round(current_price * (1 + variation + 0.002), 5),
                'low': round(current_price * (1 + variation - 0.002), 5),
                'close': round(current_price * (1 + variation), 5),
                'volume': random.randint(100, 1000)
            }
            candles.append(candle)
        
        return candles
    
    def __iter__(self):
        """Make the factory iterable (compatible with original)"""
        self._iter_index = 0
        self._candles = self.get_candles()
        return self
    
    def __next__(self):
        """Return next batch of candles"""
        if self._iter_index >= len(self._candles):
            raise StopIteration
        
        batch_size = self.params.get('count', DEFAULT_BATCH)
        batch = self._candles[self._iter_index:self._iter_index + batch_size]
        self._iter_index += batch_size
        
        # Create a response-like object
        class Response:
            def __init__(self, candles):
                self.response = {'candles': candles}
        
        return Response(batch)


def InstrumentsCandlesFactory(instrument, params=None):
    """
    InstrumentsCandlesFactory - generate candle requests (MT4 version).
    
    This factory provides a compatible interface with the original OANDA version
    but uses MT4 data source.
    
    Parameters
    ----------
    instrument : string (required)
        the instrument to create the order for (e.g., 'EURUSD')
    params: dict (optional)
        parameters specifying the historical range:
        - from: start datetime (RFC3339 format)
        - to: end datetime (RFC3339 format)
        - count: number of candles
        - granularity: candle timeframe (M1, M5, M15, H1, D, etc.)
    
    Example
    -------
    >>> from mt4_candles_factory import InstrumentsCandlesFactory
    >>> 
    >>> instrument = "EURUSD"
    >>> params = {
    ...     "from": "2024-01-01T00:00:00Z",
    ...     "granularity": "H1",
    ...     "count": 100
    ... }
    >>> 
    >>> for req in InstrumentsCandlesFactory(instrument=instrument, params=params):
    ...     candles = req.response.get('candles', [])
    ...     for candle in candles:
    ...         print(candle)
    """
    factory = MT4CandlesFactory(instrument, params)
    return factory


# For backward compatibility with OANDA code that expects this module
# to have the original class name
InstrumentsCandles = MT4CandlesFactory
